using System; using System.Collections.Generic;
namespace CodexTrayStatus { public sealed class ModelPrice { public decimal Input {get;set;} public decimal Cached {get;set;} public decimal Output {get;set;} }
internal static class PricingCatalog { private static readonly Dictionary<string,ModelPrice> overrides=new Dictionary<string,ModelPrice>(StringComparer.OrdinalIgnoreCase); internal static bool TryGet(string model,out ModelPrice price){return overrides.TryGetValue(model??"",out price);} internal static void Set(string model,ModelPrice price){if(string.IsNullOrWhiteSpace(model)||price==null||price.Input<0||price.Cached<0||price.Output<0||price.Input>100000||price.Cached>100000||price.Output>100000)throw new ArgumentException("invalid_price");overrides[model]=price;} internal static void Reset(string model){overrides.Remove(model??"");} internal static Dictionary<string,ModelPrice> Snapshot(){return new Dictionary<string,ModelPrice>(overrides,StringComparer.OrdinalIgnoreCase);} internal static void Replace(Dictionary<string,ModelPrice> values){overrides.Clear();if(values==null)return;foreach(KeyValuePair<string,ModelPrice> value in values)Set(value.Key,value.Value);} }
}
